417	// ── Inhalt einer comdare_axis_registry.xml: engine-Attr + axis-id -> {baustein name}. ──
418	struct RegistryContents {
419	    std::string                                  engine;     // Wurzel @engine ("cache_engine" / "prt_art")
420	    std::map<std::string, std::set<std::string>> axis_names; // axis-id -> {baustein name}
421	};
422	
423	// read_axis_registry — liest EINE comdare_axis_registry.xml ueber den common-DOM (KEIN regex/tinyxml2).
424	// nullopt bei Lese-/Parse-Fehler oder falschem Wurzel-Tag.
425	[[nodiscard]] inline std::optional<RegistryContents> read_axis_registry(std::filesystem::path const& registry_file) {
426	    std::ifstream in{registry_file};
427	    if (!in) return std::nullopt;
428	    std::ostringstream ss;
429	    ss << in.rdbuf();
430	    auto root = ::comdare::common::xml::parse_document(ss.str());
431	    if (!root || root->tag != "comdare_axis_registry") return std::nullopt;
432	    RegistryContents rc;
433	    rc.engine = root->attr("engine");
434	    for (auto const* axis : root->children_named("axis")) {
435	        auto& names = rc.axis_names[axis->attr("id")];
436	        for (auto const* b : axis->children_named("baustein")) names.insert(b->attr("name"));
437	    }
438	    return rc;
439	}

